func TestDistillTemplateEnvOverride(t *testing.T) {
	path := filepath.Join(t.TempDir(), "alt.md")
	content := "---\nname: alt\n---\nALT BODY with ${TAXONOMY_BLOCK}\n"
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
