package cli

import (
	"bufio"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func writeLabelFixtureRun(t *testing.T, corpusDir string) (runDir, corpusPath string) {
	t.Helper()
	corpus := distillEvalCorpus{
		RepoKey: "test/repo", CreatedAt: time.Now(), CorpusSHA256: "abc",
		Sessions: []distillEvalCorpusEntry{
			{SessionID: "s-golden", Branch: "main", TranscriptPath: "sessions/main/s-golden.jsonl", Golden: true},
			{SessionID: "s-plain", Branch: "main", TranscriptPath: "sessions/main/s-plain.jsonl"},
		},
	}
	corpusPath = filepath.Join(corpusDir, "corpus.json")
	data, _ := json.Marshal(corpus)
	if err := os.WriteFile(corpusPath, data, 0o600); err != nil {
		t.Fatal(err)
	}
	runDir = filepath.Join(corpusDir, "runs", "base")
	if err := os.MkdirAll(runDir, 0o700); err != nil {
		t.Fatal(err)
	}
	raw := strings.Join([]string{
		`{"type":"chunk","session_id":"s-golden","branch":"main","chunk_index":1,"chunk_count":1,"facts_emitted":1,"cap":6}`,
		`{"type":"fact","session_id":"s-golden","branch":"main","chunk_index":1,"fact_id":"f1","kind":"gotcha","paths":["a.b.c"],"text":"golden fact","checkpoint_id":"cp"}`,
		`{"type":"fact","session_id":"s-plain","branch":"main","chunk_index":1,"fact_id":"f2","kind":"decision","paths":["d.e.f"],"text":"plain fact","checkpoint_id":"cp"}`,
	}, "\n") + "\n"
	if err := os.WriteFile(filepath.Join(runDir, "raw-facts.jsonl"), []byte(raw), 0o600); err != nil {
		t.Fatal(err)
	}
	return runDir, corpusPath
}

func TestDistillEvalLabelsSheetCoversGoldenFactsOnly(t *testing.T) {
	runDir, corpusPath := writeLabelFixtureRun(t, t.TempDir())
	out := filepath.Join(t.TempDir(), "labels.jsonl")
	if _, err := runDistillEvalCommand(t, t.TempDir(), "labels", "--run", runDir, "--corpus", corpusPath, "--out", out); err != nil {
		t.Fatalf("labels: %v", err)
	}
	f, err := os.Open(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var sheet []distillEvalLabelLine
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		var line distillEvalLabelLine
		if err := json.Unmarshal(sc.Bytes(), &line); err != nil {
			t.Fatalf("bad sheet line %q: %v", sc.Text(), err)
		}
		sheet = append(sheet, line)
	}
	if len(sheet) != 1 {
		t.Fatalf("sheet has %d lines, want 1 (golden sessions only): %+v", len(sheet), sheet)
	}
	l := sheet[0]
	if l.FactID != "f1" || l.SessionID != "s-golden" || l.TranscriptPath != "sessions/main/s-golden.jsonl" ||
		l.Kind != "gotcha" || l.Text != "golden fact" || l.Verdict != "" {
		t.Errorf("sheet line wrong: %+v", l)
	}
}

func TestLoadDistillEvalLabelsRejectsBadVerdict(t *testing.T) {
	for _, bad := range []string{"Keep", "kil", ""} {
		path := filepath.Join(t.TempDir(), "labels.jsonl")
		content := `{"fact_id":"f1","verdict":"keep"}` + "\n" +
			`{"fact_id":"f2","verdict":"` + bad + `"}` + "\n"
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
		_, err := loadDistillEvalLabels(path)
		if err == nil || !strings.Contains(err.Error(), "line 2") {
			t.Errorf("verdict %q: expected error naming line 2, got %v", bad, err)
		}
	}
}

func TestLoadDistillEvalLabelsRoundTrip(t *testing.T) {
	path := filepath.Join(t.TempDir(), "labels.jsonl")
	content := `{"fact_id":"f1","verdict":"keep","reason":"useful"}` + "\n" +
		`{"fact_id":"f2","verdict":"kill","reason":"restates code"}` + "\n"
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	labels, err := loadDistillEvalLabels(path)
	if err != nil {
		t.Fatal(err)
	}
	if len(labels) != 2 || labels["f1"].Verdict != "keep" || labels["f2"].Verdict != "kill" || labels["f2"].Reason != "restates code" {
		t.Errorf("labels wrong: %+v", labels)
	}
}

package cli

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
)

// distillEvalLabelLine is one row of the golden label sheet: generated with an
// empty verdict, hand-filled by the owner with "keep" or "kill".
type distillEvalLabelLine struct {
	FactID         string   `json:"fact_id"`
	SessionID      string   `json:"session_id"`
	TranscriptPath string   `json:"transcript_path"`
	Kind           string   `json:"kind"`
	Paths          []string `json:"paths"`
	Text           string   `json:"text"`
	Verdict        string   `json:"verdict"`
	Reason         string   `json:"reason"`
}

type distillEvalVerdict struct {
	Verdict string // "keep" | "kill"
	Reason  string
}

// loadDistillEvalLabels reads a filled label sheet keyed by fact_id. Any
// verdict other than exactly "keep" or "kill" fails with its 1-based line
// number, so an unfilled or typoed sheet never silently scores as empty.
func loadDistillEvalLabels(path string) (map[string]distillEvalVerdict, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	labels := map[string]distillEvalVerdict{}
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if len(sc.Bytes()) == 0 {
			continue
		}
		var line distillEvalLabelLine
		if err := json.Unmarshal(sc.Bytes(), &line); err != nil {
			return nil, fmt.Errorf("%s line %d: %w", path, lineNo, err)
		}
		if line.Verdict != "keep" && line.Verdict != "kill" {
			return nil, fmt.Errorf("%s line %d: verdict must be exactly \"keep\" or \"kill\", got %q", path, lineNo, line.Verdict)
		}
		if line.FactID == "" {
			return nil, fmt.Errorf("%s line %d: missing fact_id", path, lineNo)
		}
		labels[line.FactID] = distillEvalVerdict{Verdict: line.Verdict, Reason: line.Reason}
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	return labels, nil
}

// readDistillEvalRawFacts loads the fact lines (type "fact") of a run's
// raw-facts.jsonl, plus the chunk lines (type "chunk") for callers that need
// them.
func readDistillEvalRawFacts(path string) (chunks []distillRawChunkLine, facts []distillRawFactLine, err error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for sc.Scan() {
		if len(sc.Bytes()) == 0 {
			continue
		}
		var probe struct {
			Type string `json:"type"`
		}
		if err := json.Unmarshal(sc.Bytes(), &probe); err != nil {
			return nil, nil, fmt.Errorf("%s: %w", path, err)
		}
		switch probe.Type {
		case "chunk":
			var c distillRawChunkLine
			if err := json.Unmarshal(sc.Bytes(), &c); err != nil {
				return nil, nil, err
			}
			chunks = append(chunks, c)
		case "fact":
			var fl distillRawFactLine
			if err := json.Unmarshal(sc.Bytes(), &fl); err != nil {
				return nil, nil, err
			}
			facts = append(facts, fl)
		}
	}
	return chunks, facts, sc.Err()
}

func loadDistillEvalCorpusFile(path string) (distillEvalCorpus, error) {
	var corpus distillEvalCorpus
	data, err := os.ReadFile(path)
	if err != nil {
		return corpus, fmt.Errorf("read corpus %s: %w", path, err)
	}
	if err := json.Unmarshal(data, &corpus); err != nil {
		return corpus, fmt.Errorf("decode corpus %s: %w", path, err)
	}
	return corpus, nil
}

func newDistillEvalLabelsCommand(opts Options) *cobra.Command {
	var (
		runDir     string
		corpusPath string
		out        string
	)
	cmd := &cobra.Command{
		Use:   "labels",
		Short: "Generate the golden label sheet (keep/kill, hand-filled) from a run",
		RunE: func(cmd *cobra.Command, args []string) error {
			corpus, err := loadDistillEvalCorpusFile(corpusPath)
			if err != nil {
				return err
			}
			golden := map[string]distillEvalCorpusEntry{}
			for _, s := range corpus.Sessions {
				if s.Golden {
					golden[s.SessionID] = s
				}
			}
			if len(golden) == 0 {
				return errors.New("corpus has no golden sessions")
			}
			_, facts, err := readDistillEvalRawFacts(filepath.Join(runDir, "raw-facts.jsonl"))
			if err != nil {
				return err
			}
			if out == "" {
				out = filepath.Join(runDir, "labels.jsonl")
			}
			f, err := os.Create(out)
			if err != nil {
				return err
			}
			defer f.Close()
			enc := json.NewEncoder(f)
			rows := 0
			for _, fact := range facts {
				entry, ok := golden[fact.SessionID]
				if !ok {
					continue
				}
				rows++
				if err := enc.Encode(distillEvalLabelLine{
					FactID: fact.FactID, SessionID: fact.SessionID,
					TranscriptPath: entry.TranscriptPath,
					Kind:           fact.Kind, Paths: fact.Paths, Text: fact.Text,
				}); err != nil {
					return err
				}
			}
			fmt.Fprintf(cmd.OutOrStdout(), "label sheet: %d facts from %d golden sessions → %s\nfill each verdict with keep or kill, then score with --labels\n", rows, len(golden), out)
			return nil
		},
	}
	cmd.Flags().StringVar(&runDir, "run", "", "Run directory containing raw-facts.jsonl (required)")
	cmd.Flags().StringVar(&corpusPath, "corpus", "", "Path to corpus.json (required)")
	cmd.Flags().StringVar(&out, "out", "", "Sheet path (default <run>/labels.jsonl)")
	_ = cmd.MarkFlagRequired("run")
	_ = cmd.MarkFlagRequired("corpus")
	return cmd
}

