	almost := func(got, want float64) bool { d := got - want; return d < 1e-9 && d > -1e-9 }
	if !almost(cal.Agreement, 2.0/3.0) || !almost(cal.AgreementOnKills, 0.5) || !almost(cal.AgreementOnKeeps, 1.0) {
