`
	runDir, corpusPath := writeScoreFixture(t, t.TempDir(), []string{"s1"}, raw, "")
	labelsPath := filepath.Join(runDir, "labels.jsonl")
	if err := os.WriteFile(labelsPath, []byte(`{"fact_id":"f1","verdict":"kill"}`+"\n"), 0o600); err != nil {
